import assert from 'node:assert/strict'
import {test} from 'node:test'
import {normalizeCookies} from './cookies'

// made-up values in the shape of a real export
const FILE = [
  '# Netscape HTTP Cookie File',
  '# This file is generated by an extension. Do not edit.',
  '',
  '.youtube.com\tTRUE\t/\tTRUE\t1893456000\tSID\tabc123',
  '.youtube.com\tTRUE\t/\tTRUE\t1893456000\tPREF\tf6=40000000&tz=Europe.Paris',
].join('\n')

const cookieLines = (text: string | undefined) => (text ?? '').split('\n').filter(l => l.split('\t').length === 7)

test('raw files pass through with their tabs', () => {
  const out = normalizeCookies(FILE)
  assert.equal(cookieLines(out).length, 2)
  assert.ok(out?.startsWith('# Netscape HTTP Cookie File'))
})

test('tabs flattened to spaces by a settings form are restored', () => {
  const out = normalizeCookies(FILE.replace(/\t/g, ' '))
  assert.deepEqual(cookieLines(out), cookieLines(FILE))
})

test('base64, with or without line breaks, is decoded', () => {
  const b64 = Buffer.from(FILE).toString('base64')
  assert.deepEqual(cookieLines(normalizeCookies(b64)), cookieLines(FILE))
  assert.deepEqual(cookieLines(normalizeCookies(b64.replace(/(.{60})/g, '$1\n'))), cookieLines(FILE))
})

test('a missing header is added and windows line endings are handled', () => {
  const body = FILE.split('\n').slice(3).join('\r\n')
  const out = normalizeCookies(body)
  assert.ok(out?.startsWith('# Netscape HTTP Cookie File\n'))
  assert.equal(cookieLines(out).length, 2)
})

test('empty or junk values are ignored', () => {
  assert.equal(normalizeCookies(undefined), undefined)
  assert.equal(normalizeCookies('   '), undefined)
  assert.equal(normalizeCookies('not cookies at all'), undefined)
  assert.equal(normalizeCookies(Buffer.from('hello world').toString('base64')), undefined)
})
